\documentclass{article}
% A1 portrait: 594mm x 841mm
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{fontawesome5}
\pagestyle{empty}

% ── Color Palette ──
% UNICEF cyan/blue foundation + warm amber accents
\definecolor{primary}{HTML}{006B99}      % UNICEF deep cyan-blue
\definecolor{secondary}{HTML}{00AEEF}    % UNICEF signature cyan
\definecolor{accent}{HTML}{F5A623}       % warm amber
\definecolor{accentdark}{HTML}{D4891A}   % deep amber
\definecolor{bgposter}{HTML}{F0F8FC}     % very light cyan tint
\definecolor{textdark}{HTML}{0D2B3E}     % deep navy text
\definecolor{textgray}{HTML}{3A5A6E}     % medium blue-gray
\definecolor{stathighlight}{HTML}{E8F6FC}% light cyan for stat boxes
\definecolor{amberlight}{HTML}{FFF8E8}   % light amber for warm cards
\definecolor{ambertitlebg}{HTML}{FEF0C8} % amber card title bg
\definecolor{cyanbg}{HTML}{E8F6FC}       % cyan card background
\definecolor{cyantitlebg}{HTML}{C5E9F6}  % cyan card title bg
\definecolor{darkbg}{HTML}{E8F2F7}       % dark-primary card bg
\definecolor{darktitlebg}{HTML}{CCE4F0}  % dark-primary title bg
\definecolor{warmbg}{HTML}{FEF9F0}       % warm neutral bg
\definecolor{warmtitlebg}{HTML}{FDE8C0}  % warm title bg
\definecolor{redaccent}{HTML}{E8003D}    % UNICEF red for emergencies

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=8pt, parsep=0pt, topsep=4pt,
  label={\color{secondary}\rule[0.15em]{0.5em}{0.5em}}}
\setlist[enumerate]{leftmargin=24pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Card styles ──
\tcbset{
  cyancard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cyanbg,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{30}{36}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=cyantitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  ambercard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=amberlight,
    borderline west={5pt}{0pt}{accentdark},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{30}{36}\selectfont\bfseries\color{accentdark},
    coltitle=accentdark, colbacktitle=ambertitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={accentdark!50},
    valign=top, drop shadow={opacity=0.15},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{30}{36}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=darktitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.15},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!15!white,
    borderline west={6pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{30}{36}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=5pt, bottomtitle=5pt,
    valign=top, drop shadow={opacity=0.20},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

% ══════════════════════════════════════════════
% TITLE BAR
% ══════════════════════════════════════════════
\posterbox[
  enhanced,
  colback=primary, colframe=primary,
  arc=0pt, boxrule=0pt,
  left=28pt, right=28pt, top=14pt, bottom=10pt,
  halign=center, valign=center,
  drop shadow={opacity=0.30}
]{name=title, column=1, span=2, between=top and row3}{%
  {\fontsize{12}{14}\selectfont\bfseries\color{white!60}\MakeUppercase{UNICEF Global Education Campaign}}\\[6pt]
  {\fontsize{56}{64}\selectfont\bfseries\color{white}Every Child Deserves\\[2pt]to Learn}\\[8pt]
  {\fontsize{22}{28}\selectfont\color{white!80}Millions of children worldwide are still denied their right to quality education.\\[2pt]
  UNICEF is working in \textbf{190+~countries} to change that.}
}

% ══════════════════════════════════════════════
% BIG STAT — 250 MILLION (HERO)
% ══════════════════════════════════════════════
\posterbox[
  enhanced,
  colback=secondary, colframe=secondary,
  arc=0pt, boxrule=0pt,
  left=0pt, right=0pt, top=0pt, bottom=0pt,
  halign=center, valign=center,
  drop shadow={opacity=0.20}
]{name=hero, column=1, span=2, between=row3 and row6}{%
  \begin{minipage}[c]{0.58\linewidth}
    \centering
    {\fontsize{100}{110}\selectfont\bfseries\color{white}250}\\[-8pt]
    {\fontsize{44}{52}\selectfont\bfseries\color{white}MILLION}\\[4pt]
    {\fontsize{24}{30}\selectfont\color{white!90}children \& adolescents out of school worldwide}
  \end{minipage}%
  \hfill
  \begin{minipage}[c]{0.38\linewidth}
    \centering
    \colorbox{white!20}{\parbox{0.88\linewidth}{%
      \centering\vspace{10pt}
      {\fontsize{50}{58}\selectfont\bfseries\color{white}70\%}\\[2pt]
      {\fontsize{18}{24}\selectfont\color{white!90}of children in low \& middle\\\textbf{income countries} cannot\\read by age 10}
      \vspace{8pt}
    }}
  \end{minipage}
  \hspace{8pt}
}

% ══════════════════════════════════════════════
% LEFT COLUMN — CRISIS + BARRIERS
% ══════════════════════════════════════════════

\posterbox[cyancard, title={The Scale of the Crisis}
]{name=crisis, column=1, between=row6 and row9}{%
  \fontsize{21}{30}\selectfont
  \begin{itemize}
    \item \textbf{250 million} children remain out of school — a generation of lost potential
    \item \textbf{70\%} of children in low/middle-income countries cannot read a simple text by age 10 — "learning poverty"
    \item Even attending school doesn't guarantee learning: quality, safety, and inclusion all matter
  \end{itemize}
  \vspace{6pt}
  \colorbox{primary!18}{\parbox{0.93\linewidth}{%
    \vspace{4pt}
    {\fontsize{19}{26}\selectfont\color{primary} $\Rightarrow$ Every child denied education is a missed opportunity for a healthier, more equitable world.}
    \vspace{4pt}
  }}
}

\posterbox[ambercard, title={Barriers to Education}
]{name=barriers, column=1, between=row9 and row15}{%
  \fontsize{21}{30}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item {\color{redaccent}\bfseries Conflict \& Emergencies} — Schools destroyed, teachers displaced; girls are \textbf{2.5$\times$} more likely to be out of school in crisis zones
    \item {\color{accentdark}\bfseries Poverty} — Families cannot afford fees, uniforms, or supplies; children needed for labour
    \item {\color{accentdark}\bfseries Gender Inequality} — Deeply rooted norms limit girls' access, especially at secondary level
    \item {\color{accentdark}\bfseries Disability} — \textbf{$\sim$49\%} of children with disabilities in low-income countries never enter a classroom
    \item {\color{accentdark}\bfseries Climate Change} — Floods, droughts, and extreme weather disrupt schooling for the most vulnerable
  \end{itemize}
}

\posterbox[highlightcard, title={Aligned With Global Goals}
]{name=sdg, column=1, between=row15 and row18}{%
  \fontsize{21}{30}\selectfont
  \begin{itemize}
    \item UNICEF's work supports \textbf{SDG~4}: inclusive, equitable, quality education for all
    \item Education intersects with child rights, health, nutrition, protection, and social policy
    \item A child educated today is a leader, innovator, and peacebuilder tomorrow
  \end{itemize}
}

\posterbox[cyancard, title={Key Numbers at a Glance}
]{name=keyfacts, column=1, between=row18 and bottom}{%
  \fontsize{20}{28}\selectfont
  \renewcommand{\arraystretch}{1.5}
  \begin{tabular}{@{}r@{\hspace{6pt}}l@{}}
    {\bfseries\color{primary}250M} & children out of school globally \\
    {\bfseries\color{primary}70\%} & cannot read by age 10 \\
    {\bfseries\color{primary}190+} & countries where UNICEF operates \\
    {\bfseries\color{primary}2.5$\times$} & girls' risk in crisis settings \\
    {\bfseries\color{primary}$\sim$49\%} & children with disabilities excluded \\
  \end{tabular}
}

% ══════════════════════════════════════════════
% RIGHT COLUMN — UNICEF FOCUS + ACTION
% ══════════════════════════════════════════════

\posterbox[darkcard, title={UNICEF's Education Focus Areas}
]{name=focus, column=2, between=row6 and row13}{%
  \fontsize{21}{30}\selectfont
  \vspace{2pt}
  % Early Childhood
  \colorbox{secondary!15}{\parbox{0.93\linewidth}{%
    \vspace{3pt}
    {\fontsize{19}{25}\selectfont\bfseries\color{primary} Early Childhood Development}\\[-1pt]
    {\fontsize{19}{25}\selectfont Strong foundations via pre-primary and school-readiness programmes}
    \vspace{3pt}
  }}\vspace{5pt}

  % Inclusive Education
  \colorbox{accent!15}{\parbox{0.93\linewidth}{%
    \vspace{3pt}
    {\fontsize{19}{25}\selectfont\bfseries\color{accentdark} Inclusive Education}\\[-1pt]
    {\fontsize{19}{25}\selectfont Ensuring children with disabilities and marginalised groups can access and thrive}
    \vspace{3pt}
  }}\vspace{5pt}

  % Gender Equality
  \colorbox{secondary!15}{\parbox{0.93\linewidth}{%
    \vspace{3pt}
    {\fontsize{19}{25}\selectfont\bfseries\color{primary} Gender Equality in Education}\\[-1pt]
    {\fontsize{19}{25}\selectfont Removing barriers that prevent girls from enrolling, staying, and completing school}
    \vspace{3pt}
  }}\vspace{5pt}

  % Education in Emergencies
  \colorbox{accent!15}{\parbox{0.93\linewidth}{%
    \vspace{3pt}
    {\fontsize{19}{25}\selectfont\bfseries\color{accentdark} Education in Emergencies}\\[-1pt]
    {\fontsize{19}{25}\selectfont Learning continuity for children affected by conflict, displacement, disaster}
    \vspace{3pt}
  }}\vspace{5pt}

  % Digital Learning
  \colorbox{secondary!15}{\parbox{0.93\linewidth}{%
    \vspace{3pt}
    {\fontsize{19}{25}\selectfont\bfseries\color{primary} Digital \& Innovative Learning}\\[-1pt]
    {\fontsize{19}{25}\selectfont Technology to expand access and improve learning quality}
    \vspace{3pt}
  }}\vspace{5pt}

  % Adolescent Skills
  \colorbox{accent!15}{\parbox{0.93\linewidth}{%
    \vspace{3pt}
    {\fontsize{19}{25}\selectfont\bfseries\color{accentdark} Adolescent Skills Development}\\[-1pt]
    {\fontsize{19}{25}\selectfont Equipping young people with skills for employment and lifelong learning}
    \vspace{3pt}
  }}
}

\posterbox[ambercard, title={Why Education Cannot Wait}
]{name=why, column=2, between=row13 and row17}{%
  \fontsize{21}{30}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item Education breaks cycles of poverty — a child with secondary education earns \textbf{significantly more} over their lifetime
    \item Educated girls marry later, have fewer and healthier children, and are more likely to educate their own children
    \item Communities with higher education levels show \textbf{greater resilience} to conflict, disease, and climate shocks
    \item Every extra year of schooling increases a child's future earnings by \textbf{up to 10\%}
  \end{itemize}
}

% CALL TO ACTION — Full-width bottom band
\posterbox[
  enhanced,
  colback=accent, colframe=accent,
  arc=0pt, boxrule=0pt,
  left=28pt, right=28pt, top=14pt, bottom=14pt,
  halign=center, valign=center,
  drop shadow={opacity=0.25}
]{name=cta, column=2, between=row17 and bottom}{%
  {\fontsize{34}{40}\selectfont\bfseries\color{white}Together, We Can Change This.}\\[8pt]
  {\fontsize{21}{28}\selectfont\color{white!90}
    Governments $\cdot$ Communities $\cdot$ Organizations $\cdot$ Individuals\\[4pt]
    \textbf{Invest in education. Invest in every child's future.}
  }\\[10pt]
  \colorbox{white!25}{\parbox{0.6\linewidth}{%
    \centering\vspace{6pt}
    {\fontsize{20}{26}\selectfont\bfseries\color{white} unicef.org/education}
    \vspace{6pt}
  }}
}

\end{tcbposter}
\end{document}

