\documentclass{article}
% A1 portrait: 594mm x 841mm
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Color Palette ──
\definecolor{primary}{HTML}{006B99}
\definecolor{secondary}{HTML}{00AEEF}
\definecolor{accent}{HTML}{F5A623}
\definecolor{accentdark}{HTML}{C8820A}
\definecolor{bgposter}{HTML}{EFF8FC}
\definecolor{textdark}{HTML}{0D2B3E}
\definecolor{textgray}{HTML}{3A5A6E}
\definecolor{redaccent}{HTML}{C0392B}
\definecolor{amberlight}{HTML}{FFFBF0}
\definecolor{ambertitlebg}{HTML}{FEF0C5}
\definecolor{cyanbg}{HTML}{E8F6FC}
\definecolor{cyantitlebg}{HTML}{C5E9F6}
\definecolor{darkbg}{HTML}{E8F2F7}
\definecolor{darktitlebg}{HTML}{C8E0EE}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=7pt, parsep=0pt, topsep=3pt,
  label={\color{secondary}\rule[0.15em]{0.45em}{0.45em}}}
\setlist[enumerate]{leftmargin=22pt, itemsep=6pt, parsep=0pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Card styles ──
\tcbset{
  cyancard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cyanbg,
    borderline west={5pt}{0pt}{secondary},
    left=13pt, right=11pt, top=3pt, bottom=4pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=cyantitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.14},
  },
  ambercard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=amberlight,
    borderline west={5pt}{0pt}{accentdark},
    left=13pt, right=11pt, top=3pt, bottom=4pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{accentdark},
    coltitle=accentdark, colbacktitle=ambertitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={accentdark!50},
    valign=top, drop shadow={opacity=0.14},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{primary},
    left=13pt, right=11pt, top=3pt, bottom=4pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=darktitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.14},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!12!white,
    borderline west={6pt}{0pt}{primary},
    left=13pt, right=11pt, top=3pt, bottom=4pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=5pt, bottomtitle=5pt,
    valign=top, drop shadow={opacity=0.18},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

%% ══ TITLE BAR (rows 1–3, full width) ══
\posterbox[
  enhanced,
  colback=primary, colframe=primary,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=16pt, bottom=12pt,
  halign=center, valign=center,
  drop shadow={opacity=0.28}
]{name=title, column=1, span=2, between=top and row3}{%
  {\fontsize{11}{14}\selectfont\bfseries\color{white!55}\MakeUppercase{UNICEF Global Education Campaign}}\\[5pt]
  {\fontsize{62}{72}\selectfont\bfseries\color{white}Every Child Deserves to Learn}\\[9pt]
  {\fontsize{21}{28}\selectfont\color{white!85}%
    Millions of children worldwide are still denied their right to quality education.\\[2pt]
    UNICEF is working across \textbf{190+~countries} to change that.%
  }
}

%% ══ HERO STAT BANNER (rows 3–6, full width) ══
\posterbox[
  enhanced,
  colback=secondary, colframe=secondary,
  arc=0pt, boxrule=0pt,
  left=22pt, right=22pt, top=8pt, bottom=8pt,
  halign=left, valign=center,
  drop shadow={opacity=0.18}
]{name=hero, column=1, span=2, between=row3 and row6}{%
  \hspace{14pt}%
  \begin{minipage}[c]{0.50\linewidth}
    \centering
    {\fontsize{108}{116}\selectfont\bfseries\color{white}250}\\[-12pt]
    {\fontsize{44}{52}\selectfont\bfseries\color{white}MILLION}\\[5pt]
    {\fontsize{21}{27}\selectfont\color{white!92}children \& adolescents out of school worldwide}
  \end{minipage}%
  \hfill
  \fcolorbox{white!40}{primary}{\parbox{0.34\linewidth}{%
    \centering\vspace{12pt}
    {\fontsize{56}{64}\selectfont\bfseries\color{white}70\%}\\[5pt]
    {\fontsize{19}{25}\selectfont\color{white!90}%
      of children in low \&\\middle-income countries\\[3pt]
      \textbf{cannot read by age 10}}
    \vspace{12pt}
  }}%
  \hspace{14pt}
}

%% ══ LEFT COLUMN — rows 6–18 ══

%% Crisis overview (rows 6–9)
\posterbox[cyancard, title={The Global Education Crisis}
]{name=crisis, column=1, between=row6 and row9}{%
  \fontsize{20}{29}\selectfont
  \begin{itemize}
    \item \textbf{250 million} children remain out of school — a generation of lost potential
    \item \textbf{70\%} of children in low/middle-income countries cannot read a simple text by age 10 — so-called \textit{"learning poverty"}
    \item Attending school is not enough: quality, safety, and inclusion all matter
  \end{itemize}
  \vspace{5pt}
  \colorbox{primary!16}{\parbox{0.93\linewidth}{%
    \vspace{4pt}
    {\fontsize{18}{24}\selectfont\color{primary}%
      $\Rightarrow$ Every child denied education is a missed opportunity for a healthier, more equitable world.}
    \vspace{4pt}
  }}
}

%% Barriers (rows 9–15)
\posterbox[ambercard, title={Barriers to Education}
]{name=barriers, column=1, between=row9 and row15}{%
  \fontsize{20}{29}\selectfont
  \begin{itemize}[itemsep=9pt]
    \item {\color{redaccent}\bfseries Conflict \& Emergencies} — Schools destroyed, teachers displaced;
      girls are \textbf{2.5$\times$} more likely to be out of school in crisis settings
    \item {\color{accentdark}\bfseries Poverty} — Families cannot afford fees, uniforms, or supplies;
      children needed for labour or income
    \item {\color{accentdark}\bfseries Gender Inequality} — Deeply rooted social norms continue to limit
      girls' access, especially at secondary level
    \item {\color{accentdark}\bfseries Disability} — \textbf{$\sim$49\%} of children with disabilities in
      low-income countries never set foot in a classroom
    \item {\color{accentdark}\bfseries Climate Change} — Floods, droughts, and extreme weather
      increasingly disrupt schooling for the most vulnerable
  \end{itemize}
}

%% SDG alignment (rows 15–18)
\posterbox[highlightcard, title={Aligned With Global Goals}
]{name=sdg, column=1, between=row15 and row18}{%
  \fontsize{20}{29}\selectfont
  \begin{itemize}[itemsep=9pt]
    \item UNICEF's education work supports \textbf{SDG~4} — inclusive, equitable, quality education and lifelong learning for all
    \item Education intersects with child rights, health, nutrition, child protection, and social policy
    \item A child educated today becomes a leader, innovator, and peacebuilder tomorrow
  \end{itemize}
}

%% ══ RIGHT COLUMN — rows 6–18 ══

%% UNICEF Focus Areas (rows 6–14)
\posterbox[darkcard, title={UNICEF's Education Focus Areas}
]{name=focus, column=2, between=row6 and row14}{%
  \fontsize{20}{29}\selectfont
  \vspace{2pt}
  \colorbox{secondary!14}{\parbox{0.93\linewidth}{%
    \vspace{3pt}
    {\fontsize{18}{24}\selectfont\bfseries\color{primary} Early Childhood Development}\\[-2pt]
    {\fontsize{18}{24}\selectfont Strong foundations through pre-primary education and school-readiness programmes}
    \vspace{3pt}
  }}\vspace{5pt}

  \colorbox{accent!14}{\parbox{0.93\linewidth}{%
    \vspace{3pt}
    {\fontsize{18}{24}\selectfont\bfseries\color{accentdark} Inclusive Education}\\[-2pt]
    {\fontsize{18}{24}\selectfont Ensuring children with disabilities and marginalised groups can access and thrive in school}
    \vspace{3pt}
  }}\vspace{5pt}

  \colorbox{secondary!14}{\parbox{0.93\linewidth}{%
    \vspace{3pt}
    {\fontsize{18}{24}\selectfont\bfseries\color{primary} Gender Equality in Education}\\[-2pt]
    {\fontsize{18}{24}\selectfont Removing barriers that prevent girls from enrolling, staying in, and completing school}
    \vspace{3pt}
  }}\vspace{5pt}

  \colorbox{accent!14}{\parbox{0.93\linewidth}{%
    \vspace{3pt}
    {\fontsize{18}{24}\selectfont\bfseries\color{accentdark} Education in Emergencies}\\[-2pt]
    {\fontsize{18}{24}\selectfont Learning continuity for children affected by conflict, displacement, and natural disasters}
    \vspace{3pt}
  }}\vspace{5pt}

  \colorbox{secondary!14}{\parbox{0.93\linewidth}{%
    \vspace{3pt}
    {\fontsize{18}{24}\selectfont\bfseries\color{primary} Digital \& Innovative Learning}\\[-2pt]
    {\fontsize{18}{24}\selectfont Leveraging technology to expand access and improve learning quality}
    \vspace{3pt}
  }}\vspace{5pt}

  \colorbox{accent!14}{\parbox{0.93\linewidth}{%
    \vspace{3pt}
    {\fontsize{18}{24}\selectfont\bfseries\color{accentdark} Adolescent Skills Development}\\[-2pt]
