    \vspace{3pt}
    {\fontsize{18}{24}\selectfont\bfseries\color{primary} Gender Equality in Education}\\[-2pt]
    {\fontsize{18}{24}\selectfont Removing barriers that prevent girls from enrolling, staying in, and completing school}
    \vspace{3pt}
  }}\vspace{5pt}

  \colorbox{accent!14}{\parbox{0.93\linewidth}{%
    \vspace{3pt}
    {\fontsize{18}{24}\selectfont\bfseries\color{accentdark} Education in Emergencies}\\[-2pt]
    {\fontsize{18}{24}\selectfont Learning continuity for children affected by conflict, displacement, and natural disasters}
    \vspace{3pt}
  }}\vspace{5pt}

  \colorbox{secondary!14}{\parbox{0.93\linewidth}{%
    \vspace{3pt}
    {\fontsize{18}{24}\selectfont\bfseries\color{primary} Digital \& Innovative Learning}\\[-2pt]
    {\fontsize{18}{24}\selectfont Leveraging technology to expand access and improve learning quality}
    \vspace{3pt}
  }}\vspace{5pt}

  \colorbox{accent!14}{\parbox{0.93\linewidth}{%
    \vspace{3pt}
    {\fontsize{18}{24}\selectfont\bfseries\color{accentdark} Adolescent Skills Development}\\[-2pt]
    {\fontsize{18}{24}\selectfont Equipping young people with skills for employment, civic engagement, and lifelong learning}
    \vspace{3pt}
  }}
}

%% Why education matters (rows 14–18)
\posterbox[ambercard, title={Why Education Cannot Wait}
]{name=why, column=2, between=row14 and row18}{%
  \fontsize{20}{29}\selectfont
  \begin{itemize}[itemsep=9pt]
    \item Education breaks cycles of poverty — a child with secondary schooling earns \textbf{significantly more} over their lifetime
    \item Educated girls marry later, have healthier children, and are more likely to educate their own children
    \item Communities with higher education levels show \textbf{greater resilience} to conflict, disease, and climate shocks
    \item Every extra year of schooling can increase a child's future earnings by \textbf{up to 10\%}
  \end{itemize}
}

%% ══ CALL TO ACTION — full width, rows 18–bottom ══
\posterbox[
  enhanced,
  colback=accent, colframe=accent,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=16pt, bottom=16pt,
  halign=center, valign=center,
  drop shadow={opacity=0.22}
]{name=cta, column=1, span=2, between=row18 and bottom}{%
  {\fontsize{38}{46}\selectfont\bfseries\color{white}Together, We Can Change This.}\\[10pt]
  {\fontsize{22}{30}\selectfont\color{white!92}%
    Governments $\cdot$ Communities $\cdot$ Organizations $\cdot$ Individuals\\[5pt]
    \textbf{Invest in education. Invest in every child's future.}%
  }\\[12pt]
  \colorbox{white!22}{\parbox{0.50\linewidth}{%
    \centering\vspace{7pt}
    {\fontsize{21}{27}\selectfont\bfseries\color{white} unicef.org/education}
    \vspace{7pt}
  }}
}

